public class Calmer {
    public string Label(int n) {
        if (n == 0) { return "zero"; }
        else if (n == 1) { return "v1"; }
        else if (n == 2) { return "v2"; }
        else if (n == 3) { return "v3"; }
        else if (n == 4) { return "v4"; }
        else if (n == 5) { return "v5"; }
        else if (n == 6) { return "v6"; }
        else if (n == 7) { return "v7"; }
        else if (n == 8) { return "v8"; }
        else { return "other"; }
    }
}
